out = [[0]*22 for _ in range(22)]
for color, (dr,dc) in translations.items():
    coords=[(r,c) for r,row in enumerate(test) for c,v in enumerate(row) if v==color]
    for r,c in coords:
        rr,cc=r+dr,c+dc
        if not (0<=rr<22 and 0<=cc<22): print('out bounds',color, (r,c),(rr,cc))
        if out[rr][cc] not in (0,color): print('collision',color,(rr,cc),out[rr][cc])
        out[rr][cc]=color
# place the 2-markers based on their owning shape's translations
for color, (dr,dc) in translations.items():
